/** Rust-owned contracts generated by Bindings::write_contracts. */
export interface CapabilityContract {
  readonly name: string;
  readonly version: number;
  readonly methods: readonly {
    readonly name: string;
    readonly hasRequest: boolean;
    readonly json: boolean;
  }[];
}
export interface RustCapabilityOptions {
  contract: CapabilityContract;
  manifest: string;
  watch?: string[];
  features?: string[];
  targetDirectory?: string;
}
export interface RuntimeCapability extends CapabilityContract {
  implementation: {
    kind: "project";
    manifest: string;
    watch: string[];
    features: string[];
    targetDirectory?: string;
  };
}
/** Select an implementation for a generated contract without repeating its methods. */
export function rustCapability({
  contract,
  manifest,
  watch = [],
  features = [],
  targetDirectory,
}: RustCapabilityOptions): RuntimeCapability {
  return {
    ...contract,
    implementation: {
      kind: "project",
      manifest,
      watch,
      features,
      ...(targetDirectory ? { targetDirectory } : {}),
    },
  };
}
/** Native implementation callbacks run in a replaceable Rust library. */
export interface RustWidgetOptions {
  tag: string;
  /** State/protocol schema, unchanged for ordinary implementation edits. */
  version: number;
  initialState: unknown;
  manifest: string;
  watch?: string[];
  features?: string[];
  targetDirectory?: string;
}
export interface RuntimeWidget {
  tag: string;
  version: number;
  initialState: unknown;
  implementation: RuntimeCapability["implementation"];
}
/** Register a resident state slot and a watched Rust widget implementation. */
export function rustWidget({
  tag,
  version,
  initialState,
  manifest,
  watch = [],
  features = [],
  targetDirectory,
}: RustWidgetOptions): RuntimeWidget {
  return {
    tag,
    version,
    initialState,
    implementation: {
      kind: "project",
      manifest,
      watch,
      features,
      ...(targetDirectory ? { targetDirectory } : {}),
    },
  };
}
/** Compile/watch one library once, with several independently owned exports. */
export interface RustPluginOptions {
  name: string;
  manifest: string;
  watch?: string[];
  features?: string[];
  targetDirectory?: string;
  capabilities?: CapabilityContract[];
  widgets?: { tag: string; version: number; initialState: unknown }[];
}
export interface RuntimePlugin {
  name: string;
  implementation: RuntimeCapability["implementation"];
  capabilities: CapabilityContract[];
  widgets: { tag: string; version: number; initialState: unknown }[];
}
/** Bind exports from export_plugin! without one watcher/library per consumer. */
export function rustPlugin({
  name,
  manifest,
  watch = [],
  features = [],
  targetDirectory,
  capabilities = [],
  widgets = [],
}: RustPluginOptions): RuntimePlugin {
  return {
    name,
    capabilities,
    widgets,
    implementation: {
      kind: "project",
      manifest,
      watch,
      features,
      ...(targetDirectory ? { targetDirectory } : {}),
    },
  };
}
export interface WabouProjectConfig {
  window?: {
    title?: string;
    width?: number;
    height?: number;
    decorations?: boolean;
  };
  ui?: { entry?: string };
  capabilities?: RuntimeCapability[];
  widgets?: RuntimeWidget[];
  plugins?: RuntimePlugin[];
}
/** Type-check ordinary data or an asynchronous environment-dependent factory. */
export function defineConfig<
  T extends
    | WabouProjectConfig
    | (() => WabouProjectConfig | Promise<WabouProjectConfig>),
>(config: T): T {
  return config;
}
